// === Tab: mySketch ===
// ===============================
// Sketch Summary
// 这个 p5.js 草图绘制一群彩色白鱼向右游动，并安排一条黑鱼反向穿过鱼群。
// 所有鱼共享同一套鱼身、鱼鳍、尾巴和眼睛结构；颜色、路线和泡泡效果通过顶部参数控制。
// Fish visual was inspired by <Fish race> made by Che-Yu Wu: https://openprocessing.org/@cheyuwu/910854
// ===============================

// ===============================
// Global Configuration
// 这里集中放可调参数，方便快速调整画面比例、鱼群数量、鱼的颜色、游动幅度和泡泡效果。
// ===============================

const CANVAS_WIDTH = 540;
const CANVAS_HEIGHT = 960;

const BG_COLOR = "#2272c3";
//const BG_COLOR = "#ffffff";

const FISH_SIZE = 1.0; // 所有鱼的整体缩放

const WHITE_FISH_COLOR = "#ffffff";
const WHITE_FISH_EYE = "#2272c3";
const WHITE_FISH_PALETTE = [ // 白鱼随机使用的彩色身体调色盘
  "#eef0eb",
  "#2364aa",
  "#3da5d9",
  "#73bfb8",
  "#fec601",
  "#ea7317",
];
const WHITE_FISH_STRIPE_COLOR = "#284b63"; // 白鱼身体纹理线颜色

const BLACK_FISH_COLOR = "#000000";
const BLACK_FISH_EYE = "#2272c3";
const BLACK_FISH_BODY_TOP = "#000000"; // 黑鱼上半身颜色
const BLACK_FISH_BODY_BOTTOM = "#1a1a1a"; // 黑鱼下半身颜色
const BLACK_FISH_FIN = "#333333"; // 黑鱼鱼鳍颜色
const BLACK_FISH_TAIL = "#000000"; // 黑鱼尾巴颜色
const BLACK_FISH_STRIPE = "#eef0eb"; // 黑鱼身体纹理线颜色
const BLACK_FISH_EYE_OUTER = "#eef0eb"; // 黑鱼眼睛外圈颜色
const BLACK_FISH_EYE_INNER = "#000000"; // 黑鱼眼睛内圈颜色

const BASE_SPEED = 1.2;

const WAG_SPEED = 0.12; // 鱼鳍和尾巴摆动速度
const WAG_AMPLITUDE = 0.20; // 鱼鳍和尾巴摆动幅度

const BOB_SPEED = 0.04; // 鱼群上下浮动速度
const BOB_AMPLITUDE = 2; // 鱼群上下浮动幅度

const BLACK_PATH_WAVE_SPEED = 0.015; // 黑鱼路线的上下波动速度
const BLACK_PATH_WAVE_AMPLITUDE = 1; // 黑鱼路线的上下波动幅度

const NUM_ROWS = 17; // 白鱼排列的行数
const NUM_COLS = 5; // 白鱼排列的列数
const STREAM_EXTRA_COLS = 2;

const BUBBLE_SOURCE = "white"; // 泡泡来源；改成 "black" 就只让黑鱼吐泡泡
const BUBBLE_CHANCE = 0.001; // 每帧生成泡泡的概率
const BUBBLE_MIN_SPEED = -0.4; // 泡泡最慢上升速度，负数代表向上
const BUBBLE_MAX_SPEED = -2; // 泡泡最快上升速度，数值越负越快
const BUBBLE_MIN_RADIUS = 1; // 泡泡最小尺寸
const BUBBLE_MAX_RADIUS = 15; // 泡泡最大尺寸
const BUBBLE_MAX_OPACITY = 100; // 泡泡最大透明度

let fishSchool = [];
let whiteFish = [];
let blackFish;
let bubbles = [];

// 根据浏览器窗口计算画布大小，同时保持 540:960 的竖屏比例。
function getCanvasSize() {
  const targetRatio = CANVAS_WIDTH / CANVAS_HEIGHT;
  const windowRatio = windowWidth / windowHeight;

  if (windowRatio > targetRatio) {
    const canvasHeight = windowHeight;
    return {
      width: canvasHeight * targetRatio,
      height: canvasHeight,
    };
  }

  const canvasWidth = windowWidth;
  return {
    width: canvasWidth,
    height: canvasWidth / targetRatio,
  };
}

// 单条鱼的数据和绘制逻辑。白鱼和黑鱼共用这个类，通过 kind 区分颜色、方向和路线。
class Fish {
  constructor(x, y, size, bodyColor, eyeColor, direction, kind) {
    this.x = x;
    this.y = y;
    this.startX = x;
    this.startY = y;
    this.baseY = y;
    this.pathCenterY = y;

    this.size = size;
    this.bodyColor = bodyColor;
    this.eyeColor = eyeColor;
    this.kind = kind;
    this.wrapRight = null;
    this.wrapSpan = null;

    this.color1 = bodyColor;
    this.color2 = bodyColor;
    this.finColor = null;
    this.tailColor = null;
    this.stripeColor = WHITE_FISH_STRIPE_COLOR;
    this.eyeOuterColor = "#eef0eb";
    this.eyeInnerColor = "#153243";

    if (this.kind === "white") {
      this.color1 = random(WHITE_FISH_PALETTE); // 白鱼上半身随机色
      this.color2 = random(WHITE_FISH_PALETTE.filter((c) => c !== this.color1)); // 白鱼下半身随机取不同颜色
    }

    if (this.kind === "black") {
      this.color1 = BLACK_FISH_BODY_TOP; // 黑鱼上半身固定色
      this.color2 = BLACK_FISH_BODY_BOTTOM; // 黑鱼下半身固定色
      this.finColor = BLACK_FISH_FIN; // 黑鱼鱼鳍固定色
      this.tailColor = BLACK_FISH_TAIL; // 黑鱼尾巴固定色
      this.stripeColor = BLACK_FISH_STRIPE; // 黑鱼纹理线固定色
      this.eyeOuterColor = BLACK_FISH_EYE_OUTER; // 黑鱼眼睛外圈固定色
      this.eyeInnerColor = BLACK_FISH_EYE_INNER; // 黑鱼眼睛内圈固定色
    }

    // 1 swims right, -1 swims left.
    this.direction = direction;
    this.speed = BASE_SPEED * this.direction;

    this.isActive = true;

    // Keeps the school from bobbing and wagging in robotic unison.
    this.phaseOffset = random(TWO_PI);
  }

  update(shouldWrap = true) {
    // 每帧先沿 X 轴移动；黑鱼额外拥有轻微的垂直波浪路线。
    this.x += this.speed;

    if (this.kind === "black") {
      this.baseY =
        this.pathCenterY +
        sin(frameCount * BLACK_PATH_WAVE_SPEED + this.phaseOffset) *
          BLACK_PATH_WAVE_AMPLITUDE;
    }

    this.y =
      this.baseY +
      sin(frameCount * BOB_SPEED + this.phaseOffset) * BOB_AMPLITUDE;

    if (shouldWrap) {
      this.wrapAroundScreen();
    }
  }

  wrapAroundScreen() {
    // 白鱼使用自定义 wrapSpan 保持队列连续；其他鱼使用画布边界循环。
    if (this.wrapRight !== null && this.wrapSpan !== null) {
      if (this.direction === 1 && this.x > this.wrapRight) {
        this.x -= this.wrapSpan;
      }

      return;
    }

    const margin = this.getWrapMargin();

    if (this.direction === 1 && this.x > width + margin) {
      this.x = -margin;
    }

    if (this.direction === -1 && this.x < -margin) {
      this.x = width + margin;
    }
  }

  getWrapMargin() {
    return 80 * this.size;
  }

  display() {
    if (!this.isActive) {
      return;
    }

    push();
    translate(this.x, this.y);

    // 基础鱼形朝右；direction 为 -1 时水平翻转，让黑鱼朝左游。
    scale(this.direction, 1);

    noStroke();

    this.displayColorfulFish();
    pop();
  }

  displayColorfulFish() {
    // 这里定义参考鱼风格的外形：上下两片鱼身 + 鱼鳍 + 尾巴 + 眼睛 + 身体纹理线。
    const bodyW = 62 * this.size; // 鱼身宽度
    const bodyH = 25 * this.size; // 鱼身高度
    const tailW = 18 * this.size; // 尾巴向后延伸的长度
    const tailH = 30 * this.size; // 尾巴上下展开的高度
    const finW = 14 * this.size; // 鱼鳍宽度
    const finH = 22 * this.size; // 鱼鳍厚度/高度
    const headX = bodyW * 0.45; // 鱼头端点
    const tailX = -bodyW * 0.45; // 鱼尾连接点

    const tailWag =
      sin(frameCount * WAG_SPEED + this.phaseOffset) * WAG_AMPLITUDE; // 尾巴随时间摆动
    const finWag =
      sin(frameCount * WAG_SPEED + this.phaseOffset + HALF_PI) *
      WAG_AMPLITUDE; // 鱼鳍错开相位摆动

    const bodyTopColor = color(this.color1);
    const bodyBottomColor = color(this.color2);
    const finColor = this.finColor
      ? color(this.finColor)
      : this.getDefaultFinColor();
    const tailColor = this.tailColor ? color(this.tailColor) : finColor;

    fill(bodyTopColor);
    beginShape();
    vertex(headX, 0); // 上半身和下半身共享鱼头端点，保证鱼身闭合
    vertex(tailX, 0); // 上半身和下半身共享鱼尾端点，保证鱼身闭合
    bezierVertex(
      -bodyW * 0.12,
      -bodyH * 0.46,
      bodyW * 0.25,
      -bodyH * 0.48,
      headX,
      0
    );
    endShape(CLOSE);

    // 下半身和上半身共享同一条中线端点，因此两块颜色可以拼成完整鱼身。
    fill(bodyBottomColor);
    beginShape();
    vertex(headX, 0); // 下半身从同一个鱼头端点开始
    vertex(tailX, 0); // 下半身从同一个鱼尾端点连接
    bezierVertex(
      -bodyW * 0.15,
      bodyH * 0.55,
      bodyW * 0.18,
      bodyH * 0.52,
      headX,
      0
    );
    endShape(CLOSE);

    push();
    // 画几条短线作为鱼身纹理，让鱼看起来更接近 reference 里的装饰细节。
    stroke(this.stripeColor); // 鱼身纹理线颜色
    strokeWeight(1 * this.size);
    for (let i = 0; i < 4; i++) {
      const y = (i - 1.5) * bodyH * 0.12;
      line(
        tailX + bodyW * (0.2 + i * 0.08),
        y,
        headX - bodyW * (0.16 + i * 0.08),
        y + bodyH * 0.08
      );
    }
    pop();

    push();
    // 鱼鳍是一个弯曲三角形，连接在身体中后段；finW/finH 控制它的宽厚。
    fill(finColor);
    translate(-bodyW * 0.05, bodyH * 0.04); // 鱼鳍连接在鱼身中部偏下
    rotate(finWag); // 鱼鳍轻微摆动
    beginShape();
    vertex(0, 0); // 鱼鳍根部
    vertex(-finW, -finH * 0.48); // 鱼鳍上边缘，调大 0.48 会让鱼鳍更厚
    bezierVertex(-finW * 0.5, -finH * 0.08, -finW * 0.5, finH * 0.08, -finW, finH * 0.48); // 鱼鳍外侧曲线，调控制点可改变饱满度
    vertex(0, 0);
    endShape(CLOSE);
    pop();

    push();
    // 尾巴使用同样的曲线结构，并跟随 tailWag 轻微摆动，制造游动感。
    fill(tailColor);
    translate(tailX, 0); // 尾巴从鱼身尾端长出
    rotate(tailWag); // 尾巴轻微摆动
    beginShape();
    vertex(0, 0);
    vertex(-tailW, -tailH * 0.5);
    bezierVertex(-tailW * 0.65, -tailH * 0.1, -tailW * 0.65, tailH * 0.1, -tailW, tailH * 0.5);
    vertex(0, 0);
    endShape(CLOSE);
    pop();

    fill(this.eyeOuterColor);
    ellipse(headX - bodyW * 0.16, -bodyH * 0.23, 7 * this.size);

    fill(this.eyeInnerColor);
    ellipse(headX - bodyW * 0.18, -bodyH * 0.23, 3 * this.size);
  }

  getDefaultFinColor() {
    // 白鱼没有单独指定鱼鳍颜色时，自动从上半身颜色生成一个偏深的同色系颜色。
    var finColor = color(this.color1);
    finColor.setRed(red(finColor) * 0.99);
    finColor.setGreen(green(finColor) * 0.7);
    finColor.setBlue(blue(finColor) * 0.7);
    return finColor;
  }

  getBubbleOrigin() {
    // 计算泡泡生成点：基于鱼头位置往后一点，模拟从鱼鳃附近冒泡。
    var bodyW = 62 * this.size;
    var bodyH = 25 * this.size;
    var headX = bodyW * 0.45; // 和绘制鱼身时保持一致的鱼头位置
    const gillX = headX - bodyW * 0.24; // 泡泡从鱼鳃附近生成，不从身体中心生成

    return {
      x: this.x + gillX * this.direction, // 根据游动方向自动换到真正的鱼头一侧
      y: this.y - bodyH * 0.08, // 略微靠上，贴近鱼鳃位置
    };
  }
}

function setup() {
  const canvasSize = getCanvasSize();
  createCanvas(canvasSize.width, canvasSize.height);

  createFishSchool();
}

function createFishSchool() {
  // 每次初始化或窗口变化时重建鱼群，确保位置和间距适配当前画布尺寸。
  fishSchool = [];
  whiteFish = [];
  blackFish = null;
  bubbles = [];

  const spacingX = width / NUM_COLS;
  const spacingY = height / NUM_ROWS;
  const whiteFishData = [];

  for (let row = 0; row < NUM_ROWS; row++) {
    // 偶数行和奇数行错开半个列距，形成更自然的鱼群阵列。
    const rowOffset = row % 2 === 0 ? 0 : spacingX * 0.5;

    for (
      let col = -STREAM_EXTRA_COLS;
      col < NUM_COLS + STREAM_EXTRA_COLS;
      col++
    ) {
      const x = col * spacingX + spacingX * 0.5 + rowOffset;
      var y = row * spacingY + spacingY * 0.5;

      // Slight offsets keep the staggered grid dense but not too mechanical.
      const jitterX = random(-8, 8);
      const jitterY = random(-5, 5);

      whiteFishData.push({
        x: x + jitterX,
        y: y + jitterY,
        rowOffset,
      });
    }
  }

  whiteFishData
    .sort((a, b) => {
      // 先创建靠近画面中心的鱼，让视觉密度从中心向外展开。
      const centerX = width * 0.5;
      const centerY = height * 0.5;
      return dist(a.x, a.y, centerX, centerY) - dist(b.x, b.y, centerX, centerY);
    })
    .forEach((fishData) => {
      // 每条白鱼都会在构造函数里获得固定的随机双色，避免每帧闪烁。
      const fish = new Fish(
        fishData.x,
        fishData.y,
        FISH_SIZE,
        WHITE_FISH_COLOR,
        WHITE_FISH_EYE,
        1,
        "white"
      );
      fish.wrapRight =
        (NUM_COLS + STREAM_EXTRA_COLS) * spacingX +
        spacingX * 0.5 +
        fishData.rowOffset;
      fish.wrapSpan = (NUM_COLS + STREAM_EXTRA_COLS * 2) * spacingX;

      whiteFish.push(fish);
      fishSchool.push(fish);
    });

  const outlierRow = floor(NUM_ROWS / 2);
  const outlierCol = floor(NUM_COLS * 0.65);
  const outlierX = outlierCol * spacingX + spacingX * 0.5;
  const outlierY = (outlierRow + 1) * spacingY; // 黑鱼路线下移一行，仍保持在两排白鱼之间

  blackFish = new Fish(
    outlierX,
    outlierY,
    FISH_SIZE,
    BLACK_FISH_COLOR,
    BLACK_FISH_EYE,
    -1,
    "black"
  );

  fishSchool.push(blackFish);
}

function windowResized() {
  // 窗口尺寸变化后重新计算画布和鱼群位置。
  var canvasSize = getCanvasSize();
  resizeCanvas(canvasSize.width, canvasSize.height);
  createFishSchool();
}

function draw() {
  // 主循环：先清空背景，再更新泡泡、鱼的位置和鱼的绘制。
  background(BG_COLOR);

  updateAndDrawBubbles();

  if (blackFish) {
    blackFish.update();
  }

  for (const fish of whiteFish) {
    if (!fish.isActive) {
      continue;
    }

    fish.update();
    fish.display();
    maybeEmitBubble(fish); // 当前 BUBBLE_SOURCE 为 "white" 时，白鱼有概率吐泡泡
  }

  if (blackFish) {
    blackFish.display();
    maybeEmitBubble(blackFish); // 把 BUBBLE_SOURCE 改成 "black" 后，黑鱼会从鱼鳃吐泡泡
  }
}

function updateAndDrawBubbles() {
  noStroke();

  for (const bubble of bubbles) {
    fill(255, bubble.opacity);
    ellipse(
      bubble.x + noise(bubble.y / 20, bubble.seed) * bubble.r * 0.8, // 横向漂移强度，0.8 越小越稳定
      bubble.y,
      bubble.r
    );
    bubble.y += bubble.vy; // 负数速度让泡泡向上移动
  }

  bubbles = bubbles.filter((bubble) => bubble.y > -50); // 移除已经飘出画面上方的泡泡
}

function maybeEmitBubble(fish) {
  if (!fish || fish.kind !== BUBBLE_SOURCE || random() >= BUBBLE_CHANCE) {
    return;
  }

  const origin = fish.getBubbleOrigin(); // 使用鱼鳃位置作为泡泡生成点

  bubbles.push({
    x: origin.x,
    y: origin.y,
    vy: random(BUBBLE_MIN_SPEED, BUBBLE_MAX_SPEED), // 每个泡泡有不同上升速度
    r: random(BUBBLE_MIN_RADIUS, BUBBLE_MAX_RADIUS), // 每个泡泡有不同大小
    opacity: random(0.1, BUBBLE_MAX_OPACITY), // 每个泡泡有不同透明度
    seed: random(1000), // 让每个泡泡的横向漂移不完全一样
  });
}

